arguments.command:
cat > lib/actions.sh <<'E'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The query key must use only A-Z a-z 0-9 _ . - (Cirrus Function URL rejects other keys, e.g. "/save").
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing.
action_from_query() { case "$1" in action=*) echo "${1#action=}" ;; esac; }
E
cat > tests/forms_test.sh <<'E'
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
# Every rendered form URL must have a query key valid for the Cirrus Function URL
for f in event seat refund; do
  bash bin/render $f | grep -o 'action="[^"]*"' | sed 's/action="?\([^=&"]*\).*/\1/' | grep -qvE '^[A-Za-z0-9_.-]+$' && { echo "invalid query key ($f)"; fail=1; }
done
bash bin/render refund | grep -q '?action=refund' || { echo "render refund"; fail=1; }
exit $fail
E
sed -i 's|`?/<操作名>`（lib/actions.sh の action_url）|`?action=<操作名>`（lib/actions.sh の action_url）。クエリのキーは Cirrus Function URL の制約（`A-Z a-z 0-9 _ . -` のみ）に合わせる|' docs/framework.md
bash scripts/verify.sh; echo rc=$?; cat docs/framework.md | sed -n 2p

